import styled from '@emotion/styled';

export const StyledEmbeddedBigNumbersWrapper = styled.div({
  position: 'relative',
  zIndex: 0,
  isolation: 'isolate',
});

export const StyledBigNumbersContainer = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
  gap: '16px',
  width: '100%',
  height: '168px',
  alignItems: 'stretch',

  '& .performance-tool-big-number': {
    height: '100%',

    '& .bigNumberContainer': {
      display: 'flex',
      flexDirection: 'column',
      height: '100%',
    },

    '& .bigNumberBody': {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      minHeight: 0,
    },

    '& .bigNumberCenteredWrapper': {
      flex: 1,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-around',
      gap: '12px',
      minHeight: 0,
    },

    '& .bigNumberItemContainer': {
      flex: '0 0 auto',
      display: 'flex',
      width: '100%',
    },

    '& .bigNumberCenteredSecondaryInfo': {
      flexShrink: 0,
      paddingTop: 0,
    },

    '& .bigNumberFooter': {
      flexShrink: 0,
    },

    '& p + span': {
      fontSize: '12px !important',
      lineHeight: '12px !important',
    },
  },
});

export const StyledBigNumberFooter = styled.div({
  display: 'flex',
  alignItems: 'center',
  fontFamily: 'Work Sans',
  color: '#5C5C5C',
  justifyContent: 'center',
  gap: '4px',

  p: {
    fontSize: '16px',
    fontWeight: '500',
    margin: 0,
  },
  span: {
    fontSize: '12px',
    fontWeight: '400',
  },
});
